"""Build the public 50-minute project session from selected supplied module ideas.
Private facilitation text is sealed separately, never loaded by this module.
"""
import json
from pathlib import Path
from html import escape as e

def build_pm(api):
 R=api['R'];page,heading,section,link,ul,challenge,countdown=[api[k] for k in ['page','heading','section','link','ul','challenge','countdown']]
 s=next(s for s in json.loads((R/'data/sessions.json').read_text()) if s['id']=='project-management');d=json.loads((R/'data/project-management.json').read_text());SP='sessions/project-management/';DD='downloads/project-management/';out=R/DD;out.mkdir(parents=True,exist_ok=True)
 def nav():return '<nav class="session-nav" aria-label="Project management session"><div class="container">'+''.join('<a href="@@'+SP+p+'">'+t+'</a>' for p,t in [('index.html','Overview'),('participate.html','Participate'),('toolkit.html','Toolkit and downloads'),('presenter-guide.html','Presenter guide')])+'</div></nav>'
 def show(path,title,body):page(SP+path,title,nav()+body,'sessions')
 def img(name,alt):return '<figure class="pm-visual"><img class="pm-diagram" src="@@assets/infographics/'+name+'.svg" width="1200" height="370" alt="'+e(alt)+'"><figcaption>'+e(alt)+'</figcaption></figure>'
 agenda='<ol class="agenda">'+''.join('<li><time>'+str(a['start'])+'–'+str(a['end'])+' min</time><div><strong>'+e(a['title'])+'</strong><p>Follow a worked example and consider the next decision.</p></div></li>' for a in d['agenda'])+'</ol>'
 body=heading('Project Management',s['title'],'Presenter-led models and brief decision discussions for K–12 technology leaders. No preparation or project required.')+section('<div class="split"><div class="prose"><h2>Move district initiatives beyond the rollout.</h2><p>'+e(s['fullDescription'])+'</p><div class="actions">'+link('@@'+SP+'participate.html','Follow the shared case')+link('@@'+SP+'presenter-guide.html','Open presenter guide','button ghost')+'</div><h2>Learning objectives</h2>'+ul(s['learningObjectives'])+'<h2>Success criteria</h2>'+ul(s['successCriteria'])+'</div><aside class="card"><p class="eyebrow">Your 50-minute route</p><h2>Content and conversation</h2>'+agenda+'</aside></div>')+section(img('project-route','Define the work, coordinate people, and verify delivery and adoption.')+'<div class="callout"><strong>A shared case, taught step by step.</strong><p>'+e(d['case']['facts'])+'</p><p>'+e(d['participation'])+'</p></div><p class="small muted">'+e(d['sourceNote'])+'</p>','pale')
 show('index.html',s['title'],body)
 examples='<div class="grid two">'+''.join('<article class="card"><h3>'+e(x['initiative'])+'</h3><p>'+e(x['planningQuestion'])+'</p><p><strong>Delivery KPI:</strong> '+e(x['deliveryKPI'])+'</p><p><strong>Adoption KPI:</strong> '+e(x['adoptionKPI'])+'</p></article>' for x in d['initiativeExamples'])+'</div><p class="small muted">Illustrative indicators, not district results or prescribed targets. Define each measure, baseline, target, source, owner, and review point locally.</p>'
 worked_model='<div class="callout"><h3>Completed framework for the shared case</h3><dl><dt>Outcome and boundary</dt><dd>Verify usable service in the portable classroom; exclude a district-wide network redesign.</dd><dt>Stakeholders and milestone</dt><dd>The principal sponsors the decision, facilities and IT name handoff owners, and the teacher checks classroom usability. Agree the service test after the facilities-to-IT handoff.</dd><dt>Risk and communication</dt><dd>If the prerequisite is unverified at the next check, the project lead escalates to the sponsor. Send the principal a status, blocker, owner, decision request, and next-check update.</dd><dt>Delivery and adoption KPIs</dt><dd>Record agreed service-test pass results and successful classroom use. Establish baselines and targets before acceptance; IT supplies test evidence and the teacher confirms use at the review.</dd><dt>Change support</dt><dd>Ask about the teacher’s concern, check whether the barrier is access or know-how, provide the appropriate fix or guided practice, and schedule a follow-up.</dd></dl></div>'
 sections=[]
 for a in d['agenda']:
  id=a['id'];content=''
  if id=='pm-notice':content=challenge('pm-next-action','What is the strongest next action?',['Promise a date without checking the dependency','Bring decision owners together, name the blocker, and agree an interim plan','Buy another tool before clarifying the need'],'Bring the relevant owners together, identify what each team needs, name who can resolve the dependency, and agree an interim instructional plan and a dependable next update. The case does not provide evidence for a completion date.')
  elif id=='pm-charter':content=img('pm-lifecycle','Define the need, plan owners and risks, coordinate the work, and review usefulness.')+'<div class="grid two"><div class="card"><h3>Model a boundary</h3><p><strong>In scope:</strong> restore and verify usable service in the portable classroom.</p><p><strong>Out of scope:</strong> redesign every campus network.</p></div><div class="card"><h3>Discuss the model</h3><p>The presenter supplies the charter. Discuss which outcome, exclusion, or stakeholder needs clarification; compare your reasoning with the model.</p></div></div>'
  elif id=='pm-dependencies':content=img('project-update','Make status, blocker, owner, and decision visible.')+'<div class="callout"><h3>Complete the handoff</h3><p>Before ______ can happen, ______ must be ready.</p><p>______ owns the handoff and will provide ______.</p><p>If ______ happens, we will escalate to ______.</p></div><p>Follow the presenter’s completed handoff and risk example. In a brief neighbor exchange, choose who should act next and what the update should say. Distinguish an existing issue from a possible future risk.</p>'
  elif id=='pm-adoption':content=challenge('pm-success-evidence','Which statement points to stronger acceptance evidence?',['The installation task is marked complete','The service passes agreed tests and the teacher can use it in the intended lesson'],'The second statement adds agreed tests and actual use. Verify the evidence and the acceptance owner. Delivery can be necessary without proving adoption or usefulness. Choose one delivery indicator and one use/adoption indicator; set baselines and targets from local evidence.')+img('pm-success-scorecard','Consider technical reliability, operating capacity, instructional usefulness, and adoption.')+'<p><strong>Neighbor prompt:</strong> What does the principal need in the next update? Include status, blocker, owner, next decision, and the next check.</p><details class="answer"><summary>Consider individual change</summary><p>Prosci’s ADKAR model names Awareness, Desire, Knowledge, Ability, and Reinforcement. Use questions about understanding, concerns, know-how, actual performance, and continuing support. A technical or structural barrier may need a different response from training.</p><a href="https://www.prosci.com/methodology/adkar" target="_blank" rel="noopener noreferrer">Primary ADKAR reference ↗</a></details>'
  elif id=='pm-plan':
   fields=''.join('<label for="pm-field-'+str(i)+'">'+e(label)+'</label><textarea id="pm-field-'+str(i)+'" data-label="'+e(label)+'" maxlength="3000"></textarea>' for i,label in enumerate(d['planningFields']))
   content=worked_model+'<p>Follow the completed framework below. Think quietly for one minute, compare next actions with a neighbor for two minutes, then listen to the presenter’s model decision and rationale. Optional notes are for your own use; no plan is submitted.</p><form class="reflection" id="pm-plan-form">'+fields+'<div class="actions"><button type="button" id="pm-copy">Copy plan</button><button type="button" class="button ghost" id="pm-print">Print plan</button><button type="reset" class="button ghost">Clear plan</button></div><p id="pm-plan-status" role="status"></p></form><p class="small muted">Your plan stays in page memory. Copy or print before leaving; reloading clears it.</p>'
  elif id=='pm-commit':content='<div class="callout"><h3>Name the next conversation</h3><p>Who should be involved? What decision will you request? What evidence will you bring? When will you review the result?</p></div><p>Return to the success criteria and choose one manageable next step. Keep your own copy of the plan.</p>'+link('@@'+SP+'toolkit.html','Get the planning toolkit')
  if id=='pm-adoption':content+='<h3>Apply the same framework across initiatives</h3>'+examples
  sections.append('<section class="activity" id="'+id+'"><p class="eyebrow">'+str(a['start'])+'–'+str(a['end'])+' minutes</p><h2>'+e(a['title'])+'</h2><p class="prompt">'+e(a['prompt'])+'</p>'+content+'</section>')
 show('participate.html','Project case and planning experience',heading('Participate','Follow the model. Discuss the next decision.','The presenter teaches the framework with a shared district case. Discuss a few decisions from your seat. No project, prework, or device required.')+section(countdown()+''.join(sections)))
 blocks={
 'session-handout':('Project session quick reference',[('Presenter-led workshop',s['title']+'\n'+d['participation']),('Shared district case',d['case']['facts']),('50-minute route','\n'.join(f'{a["start"]}-{a["end"]} min: {a["title"]}' for a in d['agenda'])),('Success criteria','\n'.join(s['successCriteria'])),('Takeaway framework','Scope → stakeholders → milestones → risks → communication → KPIs and sustained adoption. No project or preparation required.\nhttps://mglearn.github.io/tcea27/sessions/project-management/')]),
 'project-charter':('One-page project charter',[('Problem and intended outcome','What need does the project address? What result could be accepted?\n________________________________________________________'),('Scope and exclusions','What is included? What is explicitly outside this project?\n________________________________________________________'),('Authority and ownership','Who sponsors, approves, does, and accepts the work?\n________________________________________________________'),('Milestone and dependency','What must be ready before the next milestone? Who owns it?\n________________________________________________________'),('Risk and decision','What early signal requires attention? Who can decide?\n________________________________________________________'),('KPIs and acceptance','Name a delivery KPI and an adoption KPI, with evidence source and review point.\n________________________________________________________')]),
 'stakeholder-risk-map':('Stakeholder, dependency, and risk map',[('Stakeholder buy-in','Stakeholder/group | Impact or concern | Decision role | Engagement owner | Listening/support action\n________________________________________________________\n________________________________________________________'),('A useful handoff','Before ____ can happen, ____ must be ready.\n____ owns the handoff and will provide ____.\n________________________________________________________'),('Risk or existing issue','Event | Cause | Early signal | Response | Owner | Review date\n________________________________________________________\n________________________________________________________'),('Escalation','If ____ happens, ____ will request a decision from ____.\n________________________________________________________')]),
 'communication-scorecard':('Communication and success scorecard',[('A usable update','Audience | Question they need answered | Channel | Cadence | Author | Escalation trigger\n________________________________________________________\n________________________________________________________'),('Delivery KPI','Indicator | Baseline | Locally agreed target | Source | Owner | Review date\n________________________________________________________'),('Adoption KPI and sustained use','Indicator | Baseline | Locally agreed target | Source | Owner | Review date\n________________________________________________________'),('Resistance and sustained adoption','What concern or barrier needs attention? What response, support owner, and follow-up will sustain use?\n________________________________________________________'),('Evidence rule','A KPI is a key performance indicator tied to a project outcome. Define its calculation, baseline, target, source, owner, and review point. Do not invent baselines or targets. Choose appropriate measures after reviewing local evidence.')])}
 docs=[]
 from reportlab.platypus import SimpleDocTemplate,Spacer
 from reportlab.pdfgen import canvas
 from functools import partial
 for key,(title,parts) in blocks.items():
  story=[api['para']('TCEA 2027 | MIGUEL GUHLIN','Small27'),api['para'](title,'Title27'),api['para'](s['title'],'Small27')];html='<p class="small">'+e(s['title'])+'</p>'
  for sub,text in parts:
   story.append(api['para'](sub,'Section27'));html+='<h2>'+e(sub)+'</h2>'
   for line in text.split('\n'):story.append(api['para'](line));html+='<p>'+e(line)+'</p>'
  if key=='session-handout':
   from reportlab.graphics.barcode.qr import QrCodeWidget
   from reportlab.graphics.shapes import Drawing
   from reportlab.graphics import renderSVG
   qr=QrCodeWidget('https://mglearn.github.io/tcea27/'+SP,barLevel='M');bounds=qr.getBounds();size=bounds[2]-bounds[0];drawing=Drawing(100,100,transform=[100/size,0,0,100/size,0,0]);drawing.add(qr);story.append(drawing);renderSVG.drawToFile(drawing,str(R/'assets/images/project-management-qr.svg'));html+='<img src="../../assets/images/project-management-qr.svg" width="150" height="150" alt="QR code linking to the Project Management session">'
  story.append(api['para']('Adapted from the user-supplied TCEA Module 8 Project Management and Change Leadership assets. Fictional case; no real district data. Conference adaptation by Miguel Guhlin / MG Learn.','Small27'))
  doc=SimpleDocTemplate(str(out/(key+'.pdf')),pagesize=(612,792),rightMargin=45,leftMargin=45,topMargin=42,bottomMargin=50,title=title,author='Miguel Guhlin / MG Learn',invariant=1);doc.build(story,onFirstPage=api['footer'],onLaterPages=api['footer'],canvasmaker=partial(canvas.Canvas,invariant=1))
  page(DD+key+'.html',title,heading('Project management resource',title,'Read, adapt, or print this planning resource.')+section('<div class="prose">'+html+'<div class="actions">'+link(key+'.pdf','Download PDF')+'</div></div>'),'downloads');docs.append('<article class="download"><div><h3>'+e(title)+'</h3><p>Reusable conference planning resource.</p></div><div class="actions">'+link('@@'+DD+key+'.pdf','Download PDF','button small')+link('@@'+DD+key+'.html','Read HTML','button ghost small')+'</div></article>')
  docs[-1]=docs[-1].replace('class="button small"','class="button small"')
 toolkit=heading('Project toolkit','Small artifacts. Clearer decisions.','Follow the shared case in the session; take these templates back to support device refreshes, cybersecurity rollouts, infrastructure upgrades, and AI implementation.')+section(img('pm-toolkit','A charter, people map, update, and scorecard support project decisions.')+'<div class="download-list">'+''.join(docs)+'</div><h2 style="margin-top:40px">Change leadership models</h2>'+img('pm-adkar','ADKAR: Awareness, Desire, Knowledge, Ability, and Reinforcement. Individual change questions adapted from Prosci.')+img('pm-kotter','Kotter: explain the need, build a coalition, clarify direction, invite participation, remove barriers, show progress, maintain momentum, and embed routines. Step labels paraphrased from Kotter.')+'<h2>Frameworks and sources</h2><p>The core planning ideas are adapted from the supplied TCEA Module 8 project-management package. Its archived slides and proposed video filenames are source material, not published videos for this session.</p><p><a href="https://www.prosci.com/methodology/adkar" target="_blank" rel="noopener noreferrer">Prosci ADKAR primary reference ↗</a> · <a href="https://www.kotterinc.com/methodology/8-steps/" target="_blank" rel="noopener noreferrer">Kotter further reading ↗</a></p><p class="small muted">External references checked October 27, 2026. No numerical effectiveness claims or project-certification credit are assigned by this conference activity.</p>')
 show('toolkit.html','Project management toolkit',toolkit)
 downloads=R/'downloads.html'
 content=downloads.read_text();addition=section('<h2>Project Management resources</h2><p>Get the charter, stakeholder/risk map, communication scorecard, and session reference.</p><div class="actions">'+link('sessions/project-management/toolkit.html','Open the Project Management toolkit')+'</div>')
 content=content.replace('<section class="print-reflection',addition+'<section class="print-reflection',1);downloads.write_text(content)
 print('Built Project Management pages and four text PDFs/HTML alternatives.')
